use crate::lexer::{lex,Token,TokenKind};#[derive(Debug,Clone)]pub enum Instruction{Const(i64),Load(usize),Store(usize),Add,Sub,Mul,Div,Print,Submit(Vec<Instruction>),Wait,Halt}pub fn compile(s:&str)->Result<Vec<Instruction>,String>{Parser{t:lex(s)?,p:0,n:Vec::new(),c:Vec::new()}.program()}struct Parser{t:Vec<Token>,p:usize,n:Vec<String>,c:Vec<Instruction>}
impl Parser{fn k(&self)->&TokenKind{&self.t[self.p].kind}fn take(&mut self)->TokenKind{let x=self.t[self.p].kind.clone();self.p+=1;x}fn eat(&mut self,w:TokenKind)->Result<(),String>{let x=self.take();if std::mem::discriminant(&x)==std::mem::discriminant(&w){Ok(())}else{Err(format!("expected {w:?}, got {x:?}"))}}
fn program(mut self)->Result<Vec<Instruction>,String>{self.eat(TokenKind::Fn)?;match self.take(){TokenKind::Ident(x)if x=="main"=>{},x=>return Err(format!("expected main, got {x:?}"))}self.eat(TokenKind::LParen)?;self.eat(TokenKind::RParen)?;self.eat(TokenKind::LBrace)?;while *self.k()!=TokenKind::RBrace&&*self.k()!=TokenKind::Eof{self.stmt()?}self.eat(TokenKind::RBrace)?;self.c.push(Instruction::Halt);Ok(self.c)}
fn stmt(&mut self)->Result<(),String>{match self.take(){TokenKind::Let=>{let n=match self.take(){TokenKind::Ident(n)=>n,x=>return Err(format!("expected identifier, got {x:?}"))};self.eat(TokenKind::Equal)?;self.expr(0)?;let i=self.n.len();self.n.push(n);self.c.push(Instruction::Store(i));self.eat(TokenKind::Semicolon)},TokenKind::Print=>{self.eat(TokenKind::LParen)?;self.expr(0)?;self.eat(TokenKind::RParen)?;self.eat(TokenKind::Semicolon)?;self.c.push(Instruction::Print);Ok(())},x=>Err(format!("unsupported statement {x:?}"))}}
fn expr(&mut self,min:u8)->Result<(),String>{match self.take(){TokenKind::Number(n)=>self.c.push(Instruction::Const(n)),TokenKind::Ident(n)=>{let i=self.n.iter().position(|v|v==&n).ok_or_else(||format!("unknown variable {n}"))?;self.c.push(Instruction::Load(i))},TokenKind::LParen=>{self.expr(0)?;self.eat(TokenKind::RParen)?},TokenKind::Worker=>{self.eat(TokenKind::Dot)?;match self.take(){TokenKind::Submit=>{self.eat(TokenKind::LBrace)?;let outer=std::mem::take(&mut self.c);self.expr(0)?;let mut body=std::mem::replace(&mut self.c,outer);body.push(Instruction::Halt);self.eat(TokenKind::RBrace)?;self.c.push(Instruction::Submit(body))},TokenKind::Wait=>{self.eat(TokenKind::LParen)?;self.expr(0)?;self.eat(TokenKind::RParen)?;self.c.push(Instruction::Wait)},x=>return Err(format!("expected submit/wait, got {x:?}"))}},x=>return Err(format!("expected expression, got {x:?}"))}
loop{let(p,op)=match self.k(){TokenKind::Plus=>(1,Some(Instruction::Add)),TokenKind::Minus=>(1,Some(Instruction::Sub)),TokenKind::Star=>(2,Some(Instruction::Mul)),TokenKind::Slash=>(2,Some(Instruction::Div)),_=>(0,None)};if p==0||p<min{break}self.take();self.expr(p+1)?;self.c.push(op.unwrap())}Ok(())}}